'EPIC-008'; from __future__ import annotations; from datetime import date; from decimal import Decimal; from uuid import UUID, uuid4; from sqlalchemy import func, select; from src.extraction import TransactionDirection; from src.extraction.orm.layer2 import AtomicTransaction; from src.identity import User; from src.identity.extension.account_purge import DEFAULT_TEST_EMAIL_PATTERN, is_safe_purge_environment, owned_tables_in_delete_order, purge_test_accounts, select_test_user_ids; from src.ledger import Account; from tests.factories import AccountFactory, JournalEntryFactory, UserFactory
async def _make_user(db, email: str) -> User: user = await UserFactory.create_async(db, email=email); await db.commit(); return user
async def _user_exists(db, user_id: UUID) -> bool: db.expire_all(); result = await db.execute(select(User.id).where(User.id == user_id)); return result.first() is not None
async def _count(db, model, user_id: UUID) -> int: db.expire_all(); result = await db.execute(select(func.count()).select_from(model).where(model.user_id == user_id)); return result.scalar_one()
class TestTestAccountSelection:
    'AC-identity.purge.1 AC8.17.1'
    async def test_selection_matches_test_accounts_and_excludes_real_ones(self, db): qa = await _make_user(db, 'qa.alice@example.com'); e2e = await _make_user(db, 'e2e-bob@test.example.com'); load = await _make_user(db, 'load-test-carol@example.com'); real = await _make_user(db, 'real.person@gmail.com'); plain = await _make_user(db, 'founder@example.com'); selected = await select_test_user_ids(db, DEFAULT_TEST_EMAIL_PATTERN); emails = {email for _, email in selected}; assert {qa.email, e2e.email, load.email} <= emails; assert real.email not in emails; assert plain.email not in emails
    def test_owned_tables_cover_core_user_data_and_exclude_users(self): names = {t.name for t in owned_tables_in_delete_order()}; assert {'accounts', 'journal_entries', 'atomic_transactions', 'uploaded_documents'} <= names; assert 'users' not in names
    def test_environment_guard_allows_dev_staging_and_refuses_production(self): 'AC-identity.purge.5 AC8.17.5'; assert all((is_safe_purge_environment(safe) is True for safe in ('development', 'dev', 'local', 'staging', 'ci', 'TEST'))); assert all((is_safe_purge_environment(unsafe) is False for unsafe in ('production', 'prod', 'prd', '', None)))
class TestPurge:
    async def test_apply_purges_clean_account_and_leaves_others(self, db): 'AC-identity.purge.2 AC8.17.2'; victim = await _make_user(db, 'qa.delete-me@example.com'); victim_id = victim.id; await AccountFactory.create_async(db, user_id=victim_id, name='QA Cash'); db.add(AtomicTransaction(user_id=victim_id, txn_date=date(2024, 1, 1), amount=Decimal('10.00'), direction=TransactionDirection.IN, description='seed', currency='SGD', dedup_hash=uuid4().hex, source_documents=[])); bystander = await _make_user(db, 'real.keep-me@gmail.com'); bystander_id = bystander.id; await AccountFactory.create_async(db, user_id=bystander_id, name='Real Cash'); await db.commit(); report = await purge_test_accounts(db, apply=True); await db.commit(); assert 'qa.delete-me@example.com' in report.purged; assert not await _user_exists(db, victim_id); assert await _count(db, Account, victim_id) == 0; assert await _count(db, AtomicTransaction, victim_id) == 0; assert await _user_exists(db, bystander_id); assert await _count(db, Account, bystander_id) == 1
    async def test_account_with_posted_ledger_entry_is_blocked_not_deleted(self, db): 'AC-identity.purge.3 AC8.17.3'; protected = await _make_user(db, 'qa.has-ledger@example.com'); protected_id = protected.id; await JournalEntryFactory.create_balanced_async(db, user_id=protected_id, amount=Decimal('50.00')); await db.commit(); report = await purge_test_accounts(db, apply=True); await db.commit(); assert 'qa.has-ledger@example.com' not in report.purged; blocked_emails = {email for email, _ in report.blocked}; assert 'qa.has-ledger@example.com' in blocked_emails; assert await _user_exists(db, protected_id)
    async def test_dry_run_reports_but_persists_nothing(self, db): 'AC-identity.purge.4 AC8.17.4'; victim = await _make_user(db, 'qa.dry-run@example.com'); victim_id = victim.id; await AccountFactory.create_async(db, user_id=victim_id, name='QA Cash'); await db.commit(); report = await purge_test_accounts(db, apply=False); assert report.applied is False; assert 'qa.dry-run@example.com' in report.purged; assert await _user_exists(db, victim_id); assert await _count(db, Account, victim_id) == 1
    async def test_no_matching_accounts_is_a_noop(self, db): await _make_user(db, 'real.only@gmail.com'); report = await purge_test_accounts(db, apply=True); assert report.matched == []; assert report.purged == []; assert report.blocked == []
